package ro.leo.visual;
import android.app.*;import android.content.*;import android.os.*;
public final class AutomationService extends Service {
 boolean registered;Boolean wifi,headset;final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();
 final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){String event=null,a=i.getAction();if(Intent.ACTION_HEADSET_PLUG.equals(a)){boolean on=i.getIntExtra("state",0)==1;boolean was=headset!=null&&headset;headset=on;if(!isInitialStickyBroadcast()&&!was&&on)event="headset";}else if(Intent.ACTION_POWER_CONNECTED.equals(a))event="power";else if(android.net.wifi.WifiManager.NETWORK_STATE_CHANGED_ACTION.equals(a)){android.net.NetworkInfo info=i.getParcelableExtra(android.net.wifi.WifiManager.EXTRA_NETWORK_INFO);boolean on=info!=null&&info.isConnected(),was=wifi!=null&&wifi;wifi=on;if(!isInitialStickyBroadcast()&&!was&&on)event="wifi";}else if(android.bluetooth.BluetoothDevice.ACTION_ACL_CONNECTED.equals(a))event="bluetooth";final String selected=event;if(selected!=null)worker.execute(new Runnable(){public void run(){AutomationRules.dispatch(AutomationService.this,selected);}});}};
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int f,int id){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("leo-automation-service","Leo local rules",NotificationManager.IMPORTANCE_LOW));startForeground(736,new Notification.Builder(AutomationService.this,"leo-automation-service").setSmallIcon(android.R.drawable.ic_menu_manage).setContentTitle("Leo · Local rules active").setContentText("Disable rules in Leo Studio").setContentIntent(PendingIntent.getActivity(AutomationService.this,0,new Intent(AutomationService.this,AutomationsActivity.class),0)).build());if(!AutomationRules.enabled(AutomationService.this)){stopSelf();return START_NOT_STICKY;}if(!registered){IntentFilter filter=new IntentFilter(Intent.ACTION_HEADSET_PLUG);filter.addAction(Intent.ACTION_POWER_CONNECTED);filter.addAction(android.net.wifi.WifiManager.NETWORK_STATE_CHANGED_ACTION);filter.addAction(android.bluetooth.BluetoothDevice.ACTION_ACL_CONNECTED);registerReceiver(receiver,filter);registered=true;}return START_STICKY;}
 public void onDestroy(){if(registered)unregisterReceiver(receiver);worker.shutdownNow();stopForeground(true);super.onDestroy();}
}
